INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES (NULL, 'glowna', 'Strona Główna', '<main class=\"tresc\">\r\n\r\n\r\n\r\n<article class=\"elkatalogu\" id=\"Mąka pszenna Szymanowska typ 480 uniwersalna\">\r\n\r\n<h2>Mąka pszenna Szymanowska typ 480 uniwersalna</h2>\r\n<a href=\"produkt.html\">\r\n<img src=\"img/szymanowska.png\" style=\"width:30%; height:auto;\" alt=\"Mąka pszenna Szymanowska typ 480 uniwersalna, opakowanie 1 kilogram\">\r\n</a>\r\n<p>Mąka pszenna Szymanowska typ 480 - razem z nią możesz upiec wszystko!</p>\r\n<p>Cena 3,12 zł</p>\r\n\r\n</article>\r\n\r\n<article class=\"elkatalogu\" id=\"Mąka ziemniaczana JANEX\">\r\n<h2>Mąka ziemniaczana JANEX</h2>\r\n<img src=\"img/janex.png\" style=\"width:30%; height:auto;\" alt=\"mąka ziemniaczana janex, opakowanie jeden kilogram\">\r\n<p>Mąka ziemniaczana firmy JANEX - przydatna w każdym domu</p>\r\n<p>Cena 3,56 zł</p>\r\n</article>\r\n\r\n<article class=\"elkatalogu\" id=\"Proszek do pieczenia dr Oetker\">\r\n<h2>Proszek do pieczenia dr Oetker</h2>\r\n<img src=\"img/proszek.png\" style=\"width:30%; height:auto;\" alt=\"proszek do pieczenia doktor Oetker, opakowanie 15 gramów\">\r\n<p>Proszek do pieczenia dr Oetker - dzięki niemu każde Twoje ciasto będzie wyrastać jak szalone :D</p>\r\n<p>Cena 1,50 zł</p>\r\n</article>\r\n\r\n</main>', '1') ;
INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES (NULL, 'kontakt', 'Kontakt', '\r\n\r\n<main class=\"tresc\">\r\n<article>\r\n<h2>Podgląd lokalny. Formularz nie wysyła wiadomości</h2>\r\n<form method=\"get\" action=\"lab4.php\">\r\n<label for=\"adresemail\">Adres email</label>\r\n<input type=\"email\" name=\"email\" id=\"adresemail\" required>\r\n<p id=\"wyniki_adres_blad\" hidden></p>\r\n<label for=\"wybor\">Wybor produktu</label>\r\n<select name=\"produkt\" id=\"wybor\" required >\r\n<option value=\"\">wybierz produkt</option>\r\n<option value=\"szymanowska\" id=\"op1\">Mąka przenna Szymanowska typ 480</option>\r\n<option value=\"janex\" id=\"op2\">Mąka ziemniaczana JANEX</option>\r\n<option value=\"proszek\" id=\"op3\">Proszek do pieczenia dr Oetker</option>\r\n</select>\r\n\r\n<p id=\"wyniki_wybor_blad\" hidden></p>\r\n<label for=\"ilosc\">Ilość produktów</label>\r\n\r\n<input type=\"number\" name=\"liczba\" id=\"ilosc\" required min=\"1\" max=\"5\" step=\"1\">\r\n<p id=\"wyniki_ilosc_blad\" hidden></p>\r\n<label for=\"tekst\">Wiadomość dołączona do zamówienia</label>\r\n<input type=\"text\" name=\"wiadomosc\" id=\"tekst\" required minlength=\"10\" maxlength=\"500\">\r\n<p id=\"wyniki_wiadomosc_blad\" hidden></p>\r\n<button type=\"submit\" id=\"sprawdzacz\">Sprawdź zapytanie</button>\r\n</form>\r\n</article>\r\n<article>\r\n<p id=\"wyniki_naglowek\">Wyniki zapytania:</p>\r\n<p id=\"wyniki_adres\">Adres e-mail: </p>\r\n<p id=\"wyniki_wybor\">Produkt: </p>\r\n<p id=\"wyniki_ilosc\">Ilość: </p>\r\n<p id=\"wyniki_wiadomosc\">Wiadomość: </p>\r\n<p id=\"wyniki_wartosc\">Wartość: </p>\r\n</article>\r\n\r\n</main>', '1');
INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES (NULL, 'produkt', 'Produkt', '<main class=\"tresc\">\r\n<article>\r\n<h2>Mąka pszenna Szymanowska typ 480- razem z nią możesz upiec wszystko!</h2>\r\n<img src=\"img/szymanowska.png\" style=\"width:30%; height:auto;\" alt=\"Mąka pszenna Szymanowska typ 480 uniwersalna, opakowanie 1 kilogram\">\r\n\r\n<p>Dzięki wyspecjalizowanemu procesowi produkcyjnemu zanotowano, że dzięki tej mące współczynnik wyrastania ciasta drożdzowego jest <em>większy o nawet 13,4521 procenta!</em> Cena to jedynie<strong> 3,12 zł.</strong></p>\r\n<p>Do innych zalet tej mąki należą:\r\n<ul>\r\n<li>Jest smaczna</li>\r\n<li>Jest biała</li>\r\n<li>Pył mączny po zmieszaniu z tlenem jest materiałem wybuchowym</li>\r\n</ul>\r\n<p><a href=\"kontakt.html\">Zapytaj o produkt</a></p>\r\n\r\n<h3>Cechy Mąki pszennej Szymanowskiej typ 480 na tle mąki typ 2000</h3>\r\n<table>\r\n<caption>Porównanie mąk</caption>\r\n<thead><tr>\r\n<th scope=\"col\">Typ mąki</th>\r\n<th scope=\"col\">Kolor</th>\r\n<th scope=\"col\">Zastosowanie</th>\r\n<th scope=\"col\">Masa opakowania jednostkowego</th>\r\n</tr></thead>\r\n<tbody>\r\n<tr>\r\n<td>Typ 480</td>\r\n<td>Biały</td>\r\n<td>Uniwersalna</td>\r\n<td>Jeden kilogram</td>\r\n</tr>\r\n<tr>\r\n<td>Typ 2000</td>\r\n<td>Szary</td>\r\n<td>Pieczenie chleba, tworzenie zakwasu</td>\r\n<td>Jeden kilogram</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n</article>\r\n\r\n</main>\r\n\r\n</html>\r\n\r\n\r\n\r\n\r\n\r\n\r\n', '1');
INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES (NULL, 'filmy', 'Filmy', '<main>\r\n\r\n<h3>Mąka Szymanowska - opinia</h3>\r\n<iframe class=\"filmik\"  src=\"https://www.youtube.com/embed/gfTGQffWBRE?si=DkGu3QTW8v2D5Pck\" title=\"Unboxing mąki szymanowskiej\" frameborder=\"0\" allow=\"accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe> <p>Hiperłącze do filmu:<a href=\"https://www.youtube.com/embed/gfTGQffWBRE?si=DkGu3QTW8v2D5Pck\">YouTube</a></p>\r\n\r\n<h3>Mąka Szymanowska - fakty</h3>\r\n<iframe  class=\"filmik\" src=\"https://www.youtube.com/embed/XzFFbfH4IEg?si=NKItC5-WwAAfil8W\" title=\"Trochę o mące szymanowskiej :D\" frameborder=\"0\" allow=\"accelerometer;clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe><p>Hiperłącze do filmu:<a href=\"https://www.youtube.com/embed/XzFFbfH4IEg?si=NKItC5-WwAAfil8W\">YouTube</a></p>\r\n<h3>Wyjaśnienie na czym polega typ mąki </h3>\r\n<iframe class=\"filmik\" src=\"https://www.youtube.com/embed/EbvDRZ0iDmw?si=_tcDPYDtdUlfKs_Y\" title=\"Typy mąki wyjaśnione\" frameborder=\"0\" allow=\"accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>\r\n<p>Hiperłącze do filmu:<a href=\"https://www.youtube.com/embed/EbvDRZ0iDmw?si=_tcDPYDtdUlfKs_Y\">YouTube</a></p>\r\n\r\n\r\n</main>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n', '0');
INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES (NULL, 'lab4', 'Katalog PHP', '<?php\r\nsession_start();\r\n//walidacja danych z post \r\nrequire_once  __DIR__.\'/includes/katalog.php\';\r\nif (isset($_POST[\"produkt\"]) && isset($_POST[\"ilosc\"])){\r\n	if (filter_var($_POST[\"produkt\"], FILTER_VALIDATE_INT) && filter_var($_POST[\"ilosc\"], FILTER_VALIDATE_INT)){\r\nif ($_POST[\"ilosc\"] > 0 && $_POST[\"ilosc\"] < 6   && $_POST[\"ilosc\"] <= $produkty[$_POST[\"produkt\"]-1][\"stan\"] ){\r\n	\r\n	$_SESSION[\"ostatniwybor\"] = [\"id\" => $_POST[\"produkt\"], \"ilosc\" => $_POST[\"ilosc\"]];\r\n	header(\"Location: lab4.php\", true, 303);\r\n    exit();\r\n	}\r\n	\r\n	}else{\r\n		http_response_code(400);\r\n	}\r\n}\r\n\r\ninclude __DIR__.\'/includes/naglowek.php\';\r\n $nazwa_grupy = \'chleb\';\r\necho \"Nazwa grupy: \".$nazwa_grupy;\r\necho \"<p>Powrót do index.html: <a href=\\\"index.php?idp=glowna\\\">index.php</a>\";\r\n\r\n\r\n//filtr \r\n\r\n\r\n//post \r\n\r\n\r\n//wypisywanie filtra\r\n$iterator = 0;\r\n$rozmiar = count($produkty);\r\nwhile ($iterator < $rozmiar){\r\n\r\n	if (!isset($_GET[\"kategoria\"])){\r\n		$wyborkategorii = \"wszystko\";\r\n	}\r\n	else{\r\n		$wyborkategorii = $_GET[\"kategoria\"];\r\n	}\r\nif ($produkty[$iterator][\"kategoria\"]==$wyborkategorii || $wyborkategorii == \"wszystko\"){\r\n	if ($produkty[$iterator][\"stan\"]==0){\r\n		$stan = \"Niedostępny\";\r\n		}\r\n	elseif ($produkty[$iterator][\"stan\"]<6){\r\n		$stan = \"Niski stan\";\r\n		} \r\n	else {\r\n		$stan = \"Dostępny\";\r\n		}\r\n		\r\n	switch ($produkty[$iterator][\"kategoria\"]){\r\n		case \"ksiazki\":\r\n			$kategoria = \"Książki\";\r\n			break;\r\n		case \"akcesoria\":\r\n			$kategoria = \"Akcesoria\";\r\n			break;\r\n	}\r\n	echo \"<p>ID produktu: \".$produkty[$iterator][\"id\"].\", nazwa produktu: \".$produkty[$iterator][\"nazwa\"].\", kategoria: \".$kategoria.\", stan: \".$stan.\"</p>\";\r\n	\r\n	\r\n}\r\nelseif ($wyborkategorii != \"wszystko\" && $wyborkategorii != \"ksiazki\" && $wyborkategorii != \"akcesoria\" ) {\r\n	$wyborkategorii=\"blad\";\r\n	if ($produkty[$iterator][\"stan\"]==0){\r\n		$stan = \"Niedostępny\";\r\n		}\r\n	elseif ($produkty[$iterator][\"stan\"]<6){\r\n		$stan = \"Niski stan\";\r\n		} \r\n	else {\r\n		$stan = \"Dostępny\";\r\n		}\r\n		\r\n	switch ($produkty[$iterator][\"kategoria\"]){\r\n		case \"ksiazki\":\r\n			$kategoria = \"Książki\";\r\n			break;\r\n		case \"akcesoria\":\r\n			$kategoria = \"Akcesoria\";\r\n			break;\r\n	}\r\n	echo \"<p>ID produktu: \".$produkty[$iterator][\"id\"].\", nazwa produktu: \".$produkty[$iterator][\"nazwa\"].\", kategoria: \".$kategoria.\", stan: \".$stan.\"</p>\";\r\n	if ($iterator == $rozmiar - 1){echo \"błędny wybor kategorii, wyświetlamy całą listę\";}\r\n\r\n}\r\n$iterator++;\r\n}\r\n\r\n\r\n \r\n?>\r\n<html lang=\"pl-PL\" data-theme=\"light\" id=\"html\">\r\n<head>\r\n\r\n</head>\r\n<body>\r\n\r\n<form method=\"get\" action = \"lab4.php\"> \r\n\r\n<label for=\"kategoria\">Wybor kategorii: </label>\r\n<select name=\"kategoria\"  id=\"kategoria\" required >\r\n<option value=\"wszystko\" id=\"op1\">wszystko</option>\r\n<option value=\"ksiazki\" id=\"op2\">książki</option>\r\n<option value=\"akcesoria\" id=\"op3\">akcesoria</option>\r\n</select>\r\n\r\n<button type=\"submit\" id=\"wyslij\">Wyślij</button>\r\n</form>\r\n\r\n\r\n<form method=\"POST\" action = \"lab4.php\"> \r\n\r\n<label for=\"produkt\">ID produktu: </label>\r\n<input type=\"number\" name=\"produkt\"  id=\"produkt\" required min=\"1\" max=\"4\" step=\"1\">\r\n\r\n<label for=\"ilosc\">Ilość produktów: </label>\r\n<input type=\"number\" name=\"ilosc\"  id=\"ilosc\" required min=\"1\" max=\"5\" step=\"1\">\r\n\r\n<button type=\"submit\" id=\"wyslij2\">Wyślij</button>\r\n</form>\r\n\r\n<p> Ostatni wybór: id:<?php if (isset($_SESSION[\"ostatniwybor\"])){\r\necho $_SESSION[\"ostatniwybor\"][\"id\"].\", ilość:\". $_SESSION[\"ostatniwybor\"][\"ilosc\"];}\r\n?></p>\r\n</body>\r\n\r\n</html>\r\n\r\n', '1');